const NINTH_ORIGINAL_URL=new URL("../../../../../agent-answer-contracts/verify-phase5-capacity-prefix.mjs",import.meta.url);
import {ninthLeaf,ninthHash,ninthEntry,ninthQuestion,ninthReferenceQuestion,ninthReferenceEntry,ninthIncludes,ninthFragment,ninthSubstantiveIncludes,ninthSourceText,ninthSourceHash,ninthRegistryBefore,ninthEntryHash,ninthKeyIncludes,ninthKeyHash,ninthKeyFragment,ninthKeyQuestion} from '../../../../verify-reference.mjs';
import assert from 'node:assert/strict';import fs from 'node:fs';import {createHash} from 'node:crypto';
const sha=s=>createHash('sha256').update(s).digest('hex');
const raw=fs.readFileSync(new URL('../sixth-capacity-prefix-reconciliation.json',NINTH_ORIGINAL_URL));assert.equal(sha(raw),'e7dc30ecdb15bc1bd00ebe66e20ddbd2a961d86e1f54764da988336cfe0a6b98','reviewed five exact capacity appends');
export const capacity=JSON.parse(raw);assert.equal(capacity.schemaVersion,1);assert.equal(capacity.records.length,5);
for(const [name,hash]of Object.entries(capacity.originalFiles))assert.equal(sha(fs.readFileSync(new URL('../../../'+name,NINTH_ORIGINAL_URL))),ninthSourceHash(name,hash),'original evidence remains unchanged '+name);
for(const r of capacity.records){assert.equal(sha(r.before),r.beforeSha256);assert.equal(sha(r.after),r.afterSha256);assert.ok(r.exactAppendHtml.length>0);assert.equal(sha(r.exactAppendHtml),r.appendSha256);assert.equal(r.after,r.before+r.exactAppendHtml);assert.equal(Array.from(r.before).length,r.oldBodyCodePoints);assert.equal(Array.from(r.after).length,r.newBodyCodePoints);assert.equal(r.oldItem.a,r.before);for(const [i,b]of r.sourceBlocks.entries()){assert.equal(b.index,i);assert.equal(sha(b.html),b.sha256);assert.ok(r.before.includes(b.html));assert.ok(r.after.includes(b.html));}}
export const sandboxCapacity=capacity.records.find(r=>r.entryId==='own-os-sandbox');
export const kafkaCapacity=capacity.records.find(r=>r.entryId==='bg-kafka-4');
assert.deepEqual(sandboxCapacity.path,['items',4,'a']);assert.deepEqual(kafkaCapacity.path,['items',1,'a']);
const expected=structuredClone(capacity.sandboxBeforeEntry);assert.equal(expected.items.length,6);assert.equal(expected.items[4].a,sandboxCapacity.before);expected.items[4].a=sandboxCapacity.after;
assert.deepEqual(expected,capacity.sandboxAfterEntry);assert.equal(sha(JSON.stringify(capacity.sandboxBeforeEntry)),capacity.sandboxBeforeSha256);assert.equal(sha(JSON.stringify(expected)),capacity.sandboxAfterSha256);
export function assertCapacityPrefixes(map){for(const r of capacity.records){const e=map.get(r.entryId),actual=e?.items?.[r.path[1]];assert.ok(actual);assert.equal(actual.a,r.after,'exact approved whole capacity append '+r.entryId);assert.deepEqual({...actual,a:r.before},r.oldItem,'only the explicitly approved a changes');}assert.deepEqual(map.get('own-os-sandbox'),ninthEntry(capacity.sandboxAfterEntry),'six entire final sandbox objects exactly');return true;}
export function acceptedCapacityTargetHash(t){if(t.entryId==='own-os-sandbox'&&JSON.stringify(t.path)==='["items",4,"a"]'){assert.equal(t.afterSha256,sandboxCapacity.beforeSha256);return sandboxCapacity.afterSha256;}return ninthHash(t.entryId,t.path,t.afterSha256);}
export function acceptedCapacityEntry(c){if(c.entryId!=='own-os-sandbox')return c.afterEntry;assert.deepEqual(c.afterEntry,capacity.sandboxBeforeEntry,'original phase3 entire six-question object unchanged');return ninthEntry(capacity.sandboxAfterEntry);}
export function assertKafkaCapacity(item){assert.equal(item.a,kafkaCapacity.after);assert.deepEqual({...item,a:kafkaCapacity.before},kafkaCapacity.oldItem);return true;}
